import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create group for the card
  const group = new THREE.Group();
  group.position.set(2.5, 0.7, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Load the image texture
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);

  // Create plane geometry (standard card aspect ~1.6:1 for 512x320)
  const geometry = new THREE.PlaneGeometry(1.6, 1, 1, 1);

  // Create material with loaded texture
  const material = new MeshBasicNodeMaterial();
  texturePromise.then((texture) => {
    material.colorNode = texture;
    material.needsUpdate = true;
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Store animation timelines for cleanup
  const timelines = [];

  // State tracking
  let isHovering = false;
  let hoverTimeline = null;

  // Hover effect: rise-in (subtle, 0.15 scene units)
  const onHover = () => {
    if (isHovering) return;
    isHovering = true;

    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(group.position, {
      y: group.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
    timelines.push(hoverTimeline);
  };

  const onHoverOut = () => {
    isHovering = false;

    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(group.position, {
      y: 0.7,
      duration: 0.5,
      ease: 'power3.out'
    });
    timelines.push(hoverTimeline);
  };

  // Click effect: press-down and emit event
  const onClick = () => {
    const pressTimeline = gsap.timeline();
    timelines.push(pressTimeline);

    pressTimeline.to(group.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out'
    }, 0);

    pressTimeline.to(group.scale, {
      x: 1,
      y: 1,
      duration: 0.2,
      ease: 'back.out'
    }, 0.12);

    // Emit navigation event
    ctx.emit('hub-journal.select', {});
  };

  // Attach event handlers
  group.userData.handlers = {
    hover: onHover,
    unhover: onHoverOut,
    click: onClick
  };

  // Apply parallax-scroll primitive (trigger: scroll, intensity: 0.25)
  const primitiveResult = ctx.primitives['parallax-scroll'](group, {
    intensity: 0.25,
    trigger: 'scroll'
  });

  // Cleanup function
  group.userData.cleanup = () => {
    // Kill all GSAP timelines
    timelines.forEach(tl => tl?.kill());

    // Cleanup primitive resources
    if (primitiveResult?.cleanup) {
      primitiveResult.cleanup();
    }

    // Dispose Three.js resources
    geometry.dispose();
    material.dispose();

    // Clear handlers
    group.userData.handlers = {};
  };

  return group;
}
